function help(){if(helpState)return;helpState={markup:$('menu').innerHTML,hidden:$('menuLayer').hidden,centered:$('menuLayer').classList.contains('centered'),garage:$('menu').classList.contains('garage-menu'),multiplayer:$('menu').classList.contains('multiplayer-menu'),fields:Object.fromEntries([...$('menu').querySelectorAll('input,textarea')].filter(el=>!el.readOnly).map(el=>[el.id,el.value])),active:['racing','countdown'].includes(core.status)};if(helpState.active){if(onlineRace)onlineMenuPaused=true;else core.pause();}clearInput();menu('<div class="menu-kicker">FAHRERBESPRECHUNG</div><h2>Dein Cockpit.</h2><ul class="help-copy"><li><b>W / ↑:</b> Gas. <b>S / ↓:</b> Bremsen und rückwärts.</li><li><b>A / D oder ← / →:</b> Lenken. Vor engen Kurven kurz vom Gas!</li><li><b>Fahrzeuge:</b> Über „Zur Garage“ im Menü wählst du dein Kart und die Lackierung, mit allen Werten und dem Kart in 3D. <b>Rally Buggy</b> fährt im Gelände fast mit vollem Tempo. <b>Thunder Bolide</b> ist am schnellsten, aber träge in Kurven. <b>Pixel Flitzer</b> ist wendig und spritzig, hat aber weniger Topspeed. <b>Iron Brummer</b> ist schwer und rammt alle weg. <b>Neon Drifter</b> lädt Mini-Turbos schneller auf. <b>Apex GT</b> ist ausgewogen. Wer zu schnell lenkt, radiert Tempo weg. Ein Power-Drift kostet kein Tempo.</li><li><b>Offroad-Abkürzungen:</b> Dschungel-Tempel, Savannen-Safari und Pilzwald haben gelb beschilderte Abkürzungen über Schlamm, Staub und Wiese (gestrichelt auf der Karte). Ohne Pilz, Stern oder Turbo bist du dort sehr langsam, mit Pilz oder dem Rally Buggy sparst du viel Zeit.</li><li><b>Warnungen:</b> Kommt eine Rakete, ein roter Panzer oder ein Stern von hinten, blinkt neben deinem Kart ein Symbol mit Ausrufezeichen.</li><li><b>3D-Strecken:</b> Vulkan, Gletscher und Sternenbahn haben Brücken, Steigungen und <b>Sprungschanzen</b>. Die Schanze bringt dich auf Sprungtempo, bei der Landung gibt es einen Trick-Boost.</li><li><b>Klasse:</b> Vor dem Rennen 80, 100 oder 120 km/h wählen. Items, Turbos, Boost-Pads und Gegner werden im gleichen Verhältnis schneller, Medaillenzeiten und Bestzeiten gelten pro Klasse. Online bestimmt der Gastgeber die Klasse.</li><li><b>Power-Drift:</b> Leertaste + Lenken startet einen Drift ohne Tempoverlust. Halte ihn: Funken werden <b style="color:#3fa9ff">blau</b>, dann <b style="color:#ff8a1a">orange</b>, dann <b style="color:#c44dff">lila</b>. Lässt du los, gibt es den passenden Mini-, Super- oder Ultra-Turbo. In den Drift lenken = enger, gegenlenken = weiter. Leertaste ohne Lenken bremst.</li><li><b>Boost-Pads:</b> Die orangen Pfeilfelder auf den Geraden geben einen kurzen Schub.</li><li><b>E:</b> Item benutzen. <b>E gedrückt halten</b> hängt Banane, grünen oder roten Panzer hinten an dein Kart: Das blockt Panzer von hinten und lässt Auffahrende drehen. <b>Loslassen</b> wirft das Item nach hinten. Kurz tippen schießt Panzer wie gewohnt nach vorn. Fahr durch die bunten ?-Boxen, um eins zu bekommen: <b>Pilz</b> = kurzer Turbo, <b>Stern</b> = 7 s unverwundbar mit 100 km/h, wer dich berührt, dreht sich. <b>Grüner Panzer</b> fliegt geradeaus und prallt 3-mal von der Bande ab. <b>Roter Panzer</b> verfolgt den Fahrer vor dir. <b>Banane</b> legst du hinter dich. <b>Dreifach-Pilz</b> = drei Turbos nacheinander (dreimal E). <b>Blauer Panzer</b> (höchstens 2 pro Rennen, nie für die Spitze): fliegt über alle hinweg zum Ersten und explodiert dort, wer daneben fährt, dreht sich mit. <b>Rakete</b> (nur für die letzten beiden): 5 s mit 150 km/h auf Autopilot exakt in der Streckenmitte, wer im Weg ist, fliegt zur Seite.</li><li>Je weiter hinten du liegst, desto stärker die Items.</li><li><b>Rammen erlaubt:</b> Alle 8 Autos sind echte Körper und prallen voneinander ab. Schwere Teams wie Brutus Motorsport und Iron Ramblers schieben härter, Rammböcke drücken dich gern an die Bande.</li><li><b>G:</b> Grafikqualität (Ultra mit Ambient Occlusion, Hoch, Schnell).</li><li><b>Windschatten:</b> Direkt hinter einem Gegner bekommst du mehr Endgeschwindigkeit, die Gegner nutzen das auch.</li><li><b>C:</b> Kamera wechseln. <b>R:</b> Auto ausrichten. <b>P / Escape:</b> Pause.</li><li><b>Karriere:</b> Punkte für Chips (25), Drifts und sauberes Fahren. Jedes Finish gibt mindestens 400 XP. Alle Strecken sind von Anfang an frei.</li><li>Fahre drei Runden in Pfeilrichtung. Alle Kontrollpunkte müssen der Reihe nach passiert werden.</li><li>Handy: Pfeile links, Gas, Drift und Boost rechts. Querformat gibt dir mehr Überblick.</li></ul><button class="primary" data-action="close-help">AB AUF DIE STRECKE <span>↗</span></button>');}
function closeHelp(){if(!helpState)return;const saved=helpState;helpState=null;if(saved.active){if(onlineRace)onlineMenuPaused=false;else core.resume();$('menuLayer').hidden=true;renderer.domElement.focus({preventScroll:true});}else{$('menu').innerHTML=saved.markup;$('menuLayer').hidden=saved.hidden;$('menuLayer').classList.toggle('centered',saved.centered);$('menu').classList.toggle('garage-menu',saved.garage);$('menu').classList.toggle('multiplayer-menu',saved.multiplayer);document.querySelector('.location-tag').hidden=saved.centered;}clearInput();if(onlineLobbyOpen){renderOnlineLobby(true);Object.entries(saved.fields||{}).forEach(([id,value])=>{if($(id))$(id).value=value;});}}
function finishRace(event){
  if(chosenMode==='online'&&onlineRace){finishOnline(event);return;}
  clearInput();
  const result=calculateResult({raceId,map:{...activeMap,parTimes:parFor(activeMap,core.cc||80)},mode:recordMode(chosenMode,core.cc||80),time:event.time,bestLap:event.bestLap,position:event.position,stats:core.stats,coins:collectedCoins});
  const award=applyResult(profile,result);profile=award.profile;finishAward=award;
  if(!saveProfile(profile)&&!saveWarning){saveWarning=true;toast('Der Browser blockiert das Speichern. Dein Fortschritt bleibt für diese Sitzung erhalten.',5000);}
  const medal=result.medal,level=getLevel(profile.totalXP),unlocked=award.newMaps||[];
  const nextMap=unlocked[0]||MAPS.find(m=>m.index>activeMap.index&&unlockedMaps(profile).includes(m.id))?.id;
  const headline=chosenMode==='time'?'Zeit gesetzt.':event.position===1?'Sieg! Champagner!':event.position<=3?'Ab aufs Podium.':'Finish ist Fortschritt.';
  menu(`<div class="menu-kicker">${award.levelUp?'LEVEL AUFSTIEG!':award.newBest?'NEUE BESTZEIT':activeMap.name.toUpperCase()+' · ZIELFLAGGE'}</div><h2>${headline}</h2><div class="reward-summary"><div class="reward-medal ${medal}">${medalSymbols[medal]}<small>${medalNames[medal]}</small></div><div><strong>+${award.pointsEarned.toLocaleString('de-DE')}</strong><span>PUNKTE <b>+${award.xpEarned} XP</b></span></div></div><div class="result-stats"><div><small>RENNZEIT</small><b>${formatTime(event.time)}</b></div><div><small>${chosenMode==='time'?'BESTE RUNDE':'PLATZIERUNG'}</small><b>${chosenMode==='time'?formatTime(event.bestLap):'P'+event.position+' / '+GRID_SIZE}</b></div></div><div class="score-breakdown">${[...result.breakdown,...award.bonusBreakdown].filter(r=>r.points>0).map(r=>`<span>${r.label}<b>+${r.points}</b></span>`).join('')}</div><div class="finish-career"><span>LVL ${level.level} · ${level.title}</span><b>${profile.totalXP} XP</b><div><i style="width:${level.progress*100}%"></i></div></div>${unlocked.length?`<div class="unlock-notice">🔓 NEUE STRECKE: ${MAPS.find(m=>m.id===unlocked[0])?.name.toUpperCase()}</div>`:''}${award.newChallenges?.length?'<p class="challenge-earned">✦ Neue Streckenaufgabe geschafft!</p>':''}<button class="primary" data-action="${nextMap?'next':'restart'}" ${nextMap?'data-next="'+nextMap+'"':''}>${nextMap?'NÄCHSTE STRECKE':'NOCH EIN GRAND PRIX'} <span>↗</span></button><div class="result-actions"><button class="secondary" data-action="restart">Nochmal · Bestzeit jagen</button><button class="secondary" data-action="menu">Zur Streckenauswahl</button></div>`);
  audio.bleep('finish');$('countdown').hidden=true;$('announcer').textContent=`Rennen beendet. ${award.pointsEarned} Punkte, ${award.xpEarned} XP. ${unlocked.length?'Neue Strecke freigeschaltet.':''}`;
}
let lastBumpToast=0;core.onEvent=e=>{if(e.type==='remotehit'&&e.target&&e.target.botIndex!=null&&onlineRace){botHitQueue.push({id:Math.random().toString(36).slice(2,10),bot:e.target.botIndex,k:e.kind,t:performance.now()});}if(e.type==='item'&&e.item==='rocket'){if(e.by==='player'){toast('RAKETE! 150 KM/H',1500);shake=.25;audio.bleep('boost');}}if(e.type==='drifttier'){audio.bleep('tick');}if(e.type==='turbo'){audio.bleep('boost');if(e.kind.startsWith('drift'))toast(TIER_NAMES[+e.kind.slice(5)],700);if(e.kind==='trick')toast('TRICK-BOOST!',650);}if(e.type==='jump'){audio.bleep('go');shake=Math.max(shake,.08);}if(e.type==='land'){shake=Math.max(shake,.16);spark(core.player.x,core.player.z,14);}if(e.type==='itembox')audio.bleep('coin');if(e.type==='itemready')audio.bleep('tick');if(e.type==='itemhit'){const K={green:'GRÜNER PANZER',red:'ROTER PANZER',banana:'BANANE',star:'STERN',blue:'BLAUER PANZER'}[e.kind]||'TREFFER';if(e.victim==='player'){toast('GETROFFEN · '+K,1400);shake=Math.max(shake,.35);audio.bleep('hit');spark(e.x,e.z,26);}else{if(e.by==='player'){toast('TREFFER! '+String(e.victim).toUpperCase()+' DREHT SICH',1400);audio.bleep('lap');}if(Math.hypot(e.x-core.player.x,e.z-core.player.z)<30)spark(e.x,e.z,16);}}if(e.type==='remotehit'){toast('TREFFER!',900);audio.bleep('lap');}if(e.type==='blueboom'){spark(e.x,e.z,40,e.y);if(e.player){shake=Math.max(shake,.5);audio.bleep('hit');}}if(e.type==='shieldblock'){if(e.player){toast('ABGEWEHRT!',900);audio.bleep('hit');}if(Math.hypot(e.x-core.player.x,e.z-core.player.z)<30)spark(e.x,e.z,18);}if(e.type==='trail')audio.bleep('tick');if(e.type==='item'&&e.by==='bot'&&e.item==='star'&&Math.abs(core.position-1)<8){}if(e.type==='bump'){const d=Math.hypot(e.x-core.player.x,e.z-core.player.z);if(e.player){audio.bleep('hit');shake=Math.max(shake,Math.min(.4,.08+e.strength*.035));spark(e.x,e.z,Math.min(34,8+Math.round(e.strength*4)));if(e.strength>4.5&&performance.now()-lastBumpToast>2500){lastBumpToast=performance.now();toast('RAMMSTOSS · '+e.other.toUpperCase(),1100);}}else if(d<16){spark(e.x,e.z,10);if(d<7)shake=Math.max(shake,.06);}}if(e.type==='overtake'&&chosenMode==='race'){toast('ÜBERHOLT · P'+e.position,900);}if(e.type==='go'){audio.bleep('go');goUntil=performance.now()+800;toast('GRÜN! '+activeMap.name+' wartet.',1600);}if(e.type==='collision'){audio.bleep('hit');shake=.18;spark();}if(e.type==='boost')audio.bleep('boost');if(e.type==='lap'){if(e.lapsCompleted<3)resetCoins();audio.bleep('lap');if(e.lapsCompleted<3)toast(`RUNDE ${e.lapsCompleted} · ${formatTime(e.lapTime)} — ${e.lapsCompleted===2?'Letzte Runde!':'Weiter so!'}`,2800);}if(e.type==='finish')finishRace(e);};
function updateHud(){const p=core.player,kmh=Math.round(Math.abs(p.speed)*3.6);$('lap').innerHTML=core.lap+'<span> / 3</span>';$('timer').textContent=formatTime(core.elapsed);$('bestLap').textContent=formatTime(core.bestLap);$('speed').textContent=kmh;$('gear').textContent=p.speed<-.1?'R':p.speed<.4?'N':String(Math.min(6,1+Math.floor(p.speed/(4.6*(core.cc||80)/80))));$('position').textContent=chosenMode==='online'?(()=>{const r=onlineFieldRank(),pg=network.state.role==='guest'&&network.state.ping?` · ${network.state.ping} MS`:'';return `P${r.rank} / ${r.n}${pg}`;})():chosenMode==='time'?'TIME TRIAL':`P${core.position} / ${GRID_SIZE}`;updatePlace();$('speedBars').querySelectorAll('i').forEach((el,i)=>el.classList.toggle('active',i<Math.ceil(kmh/(112*(core.cc||80)/80)*14)));if(chosenMode==='online')renderOnlineLeaderboard();if(chosenMode==='race'){const entries=[{name:'DU · #07',color:chosenColor,progress:core.playerProgress,self:true},...core.rivals].sort((a,b)=>b.progress-a.progress);$('driverRows').innerHTML=entries.map((e,i)=>`<div class="driver${e.self?' self':''}" style="--driver-color:${typeof e.color==='number'?'#'+e.color.toString(16).padStart(6,'0'):e.color}"><span class="rank">${i+1}</span><span class="driver-color"></span><b>${e.name}</b><small>${e.self?'DU':e.tag}</small></div>`).join('');}const t=core._lastTrackT;const sector=[...activeMap.sectors].reverse().find(s=>t>=s.t)?.name||activeMap.name;if(sector!==prevSector){$('sectorName').textContent=sector;prevSector=sector;}$('styleScore').textContent=stylePoints().toLocaleString('de-DE');$('chipCount').textContent=collectedCoins+' / 36';$('driftCount').textContent=(core.stats?.driftSeconds||0).toFixed(1)+'s';const PT=parFor(activeMap,core.cc||80),medalTarget=core.elapsed<PT.gold?'gold':core.elapsed<PT.silver?'silver':core.elapsed<activeMap.parTimes.bronze?'bronze':'none';$('medalTarget').textContent=medalTarget==='none'?'JEDES FINISH ZÄHLT':medalNames[medalTarget]+' ≤ '+formatTime(PT[medalTarget],false);drawMap();}
function drawMap(){const cv=$('minimap'),c=cv.getContext('2d'),MW=cv.width,MH=cv.height;c.clearRect(0,0,MW,MH);const mm=mapFit(track,MW,MH,14),pos=(x,z)=>({x:mm.ox+x*mm.k,y:mm.oy+z*mm.k});c.lineJoin='round';c.lineCap='round';c.beginPath();TRACK.forEach((p,i)=>{const s=pos(p.x,p.z);i?c.lineTo(s.x,s.y):c.moveTo(s.x,s.y);});c.closePath();c.strokeStyle='#65877b55';c.lineWidth=14;c.stroke();c.strokeStyle='#d6e3d6aa';c.lineWidth=4;c.stroke();c.setLineDash([3,3]);c.strokeStyle='#d8a560';c.lineWidth=3;for(const sc of track.shortcuts){c.beginPath();sc.pts.forEach((p,i)=>{const q=pos(p.x,p.z);i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);});c.stroke();}c.setLineDash([]);const s=sampleTrack(0),start=pos(s.x,s.z);c.strokeStyle='#ff8459';c.lineWidth=3;c.beginPath();c.moveTo(start.x+s.nx*8,start.y+s.nz*8);c.lineTo(start.x-s.nx*8,start.y-s.nz*8);c.stroke();for(const e of (chosenMode==='online'?[...[...remoteCars.values()].map(r=>({x:r.car.position.x,z:r.car.position.z,color:Number(r.color.replace('#','0x'))})),...(core.keepBotsRacing?core.rivals:[...onlineBots.values()].map(b=>({x:b.rx??0,z:b.rz??0,color:RIVAL_ROSTER[b.n].color})))]:core.rivals)){const s=pos(e.x,e.z);c.fillStyle='#'+e.color.toString(16).padStart(6,'0');c.beginPath();c.arc(s.x,s.y,4.2,0,Math.PI*2);c.fill();}const p=pos(core.player.x,core.player.z);c.save();c.translate(p.x,p.y);c.rotate(-core.player.angle);c.fillStyle='#ff683e';c.strokeStyle='#fff6db';c.lineWidth=1.5;c.beginPath();c.moveTo(0,7);c.lineTo(-5,-4.5);c.lineTo(5,-4.5);c.closePath();c.stroke();c.fill();c.restore();}
let lastPlace=0;
function updatePlace(){if($('placeHud').hidden)return;let rank=core.position,n=GRID_SIZE,note='';if(chosenMode==='online'){const r=onlineFieldRank();rank=r.rank;n=r.n;if(network.state.role==='guest'&&network.state.ping)note=network.state.ping+' MS';}$('placeNum').textContent=rank;$('placeOf').textContent='/ '+n;$('placeNote').textContent=note;$('placeHud').classList.toggle('p1',rank===1);if(rank!==lastPlace){$('placeHud').classList.remove('bump');void $('placeHud').offsetWidth;$('placeHud').classList.add('bump');lastPlace=rank;}}
// Danger from behind (rocket, red shell aimed at me, star) as a small icon with "!" next to my kart.
const threatV=new THREE.Vector3();let lastThreat='';
function updateThreats(){
  const el=$('threatHud');if(!['racing'].includes(core.status)||cameraMode===1){if(!el.hidden)el.hidden=true;return;}
  const L=core.track.length,me=core.playerProgress,list=new Set();
  const behind=(prog,m)=>{const d=(me-prog)*L;return d>-2&&d<m;};
  for(const b of core.rivals){if(b.rocketT>0&&behind(b.progress,170))list.add('rocket');if(b.starT>0&&behind(b.progress,45))list.add('star');}
  for(const sh of core.shells){if(sh.type==='red'&&sh.target===core.player&&sh.owner!==core.player)list.add('red');if(sh.type==='blue'&&sh.target===core.player&&!(sh.boom>0))list.add('blue');}
  if(onlineRace){for(const e of remoteCars.values()){const t=e.target;if(t.rocket&&behind(t.progress??0,170))list.add('rocket');else if(t.star&&behind(t.progress??0,45))list.add('star');}
    for(const e of onlineBots.values()){const t=e.target;if(t.rocket&&behind(t.progress??0,170))list.add('rocket');else if(t.star&&behind(t.progress??0,45))list.add('star');}
    for(const it of core.externalItems){if(it.type==='red'&&Math.hypot(it.x-core.player.x,it.z-core.player.z)<30)list.add('red');if(it.type==='blue'&&!it.b&&onlineFieldRank().rank===1)list.add('blue');}}
  const key=[...list].join(',');if(!key){if(!el.hidden)el.hidden=true;lastThreat='';return;}
  if(key!==lastThreat){el.innerHTML=[...list].map(k=>`<i>${ITEM_SVG[k]}<b>!</b></i>`).join('');lastThreat=key;audio.bleep('tick');}
  threatV.copy(playerCar.position);threatV.y+=1.1;threatV.project(camera);
  el.style.left=((threatV.x*.5+.5)*innerWidth+86)+'px';el.style.top=((-threatV.y*.5+.5)*innerHeight)+'px';el.hidden=false;
}
function resize(){if(!renderer)return;renderer.setSize(innerWidth,innerHeight);composer?.setSize(innerWidth,innerHeight);bloomPass?.setSize(innerWidth,innerHeight);gtaoPass?.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}





