$('pause').addEventListener('click',()=>{if(helpState)closeHelp();else if(core.status==='paused'||onlineMenuPaused)resume();else pause();});$('help').addEventListener('click',help);function changeCamera(){cameraMode=(cameraMode+1)%3;toast(['VERFOLGERKAMERA','COCKPIT-KAMERA','WEITWINKEL-KAMERA'][cameraMode],1500);}$('camera').addEventListener('click',changeCamera);$('sound').addEventListener('click',async()=>{const on=await audio.toggle();$('sound').setAttribute('aria-pressed',String(on));$('sound').setAttribute('aria-label',on?'Sound ausschalten':'Sound einschalten');$('sound').querySelector('span').textContent=on?'SOUND AN':'SOUND AUS';});$('fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Vollbild ist hier gerade nicht verfügbar.');}});
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(e.target instanceof Element&&e.target.matches('input,textarea,select,[contenteditable=true]'))return;if(garageOpen){if(k==='arrowleft'||k==='a')garageStep(-1);else if(k==='arrowright'||k==='d')garageStep(1);else if(k==='enter')garageSelect();else if(k==='escape')closeGarage();e.preventDefault();return;}if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(['p','escape'].includes(k)&&!e.repeat){if(helpState)closeHelp();else if(core.status==='paused'||onlineMenuPaused)resume();else pause();return;}if(k==='c'&&!e.repeat)changeCamera();if(k==='g'&&!e.repeat&&renderer)setGraphics(gfx+1);if(k==='e'&&!e.repeat&&!onlineMenuPaused){const r=core.itemPress();if(r&&r!=='trail')audio.bleep('boost');}if(k==='r'&&!e.repeat&&core.status==='racing'){core.respawn();toast('AUTO AUSGERICHTET',1200);}keys.add(k);});document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys.delete(k);if(k==='e'&&core.itemRelease())audio.bleep('boost');});window.addEventListener('blur',()=>{clearInput();core.itemRelease();if(['racing','countdown'].includes(core.status))pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(['racing','countdown'].includes(core.status))pause();}});window.addEventListener('resize',resize);
$('touchBoost').addEventListener('pointerdown',()=>{const r=core.itemPress();if(r&&r!=='trail')audio.bleep('boost');});for(const ev of ['pointerup','pointercancel','pointerleave'])$('touchBoost').addEventListener(ev,()=>{if(core.itemRelease())audio.bleep('boost');});for(const [id,key] of [['left','left'],['right','right'],['touchGas','gas'],['touchBrake','brake']]){const b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();touch[key]=true;b.classList.add('pressed');b.setPointerCapture(e.pointerId);});const release=()=>{touch[key]=false;b.classList.remove('pressed');};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);}
function disposeGroup(group){if(!group)return;scene.remove(group);const geometries=new Set(),materials=new Set(),textures=new Set();group.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)for(const m of Array.isArray(o.material)?o.material:[o.material]){materials.add(m);for(const k of ['map','alphaMap','roughnessMap','bumpMap'])if(m[k]&&!m[k].userData.shared)textures.add(m[k]);}});geometries.forEach(g=>g.dispose());textures.forEach(t=>t.dispose());materials.forEach(m=>m.dispose());}
