function selectMap(id){const selected=MAPS.find(m=>m.id===id);if(!selected)return;chosenMap=id;activeMap=selected;track=getTrack(id);TRACK=track.points;TRACK_WIDTH=track.width;TRACK_LENGTH=track.length;core.setTrack(id);cameraMode=0;prevSector='';padCooldown=0;collectedCoins=0;disposeGroup(trackGroup);disposeGroup(decorGroup);disposeGroup(coinGroup);buildTrack();decorGroup=makeDecor();scene.add(decorGroup);setupCoins();applyTheme();const s=sampleTrack(0);playerCar.position.set(s.x,s.y,s.z);playerCar.rotation.y=s.angle;createGridPreview();if(!onlineLobbyOpen)renderGarage();}
function mapFit(t,w,h,pad){let x0=1e9,x1=-1e9,z0=1e9,z1=-1e9;for(const p of t.points){x0=Math.min(x0,p.x);x1=Math.max(x1,p.x);z0=Math.min(z0,p.z);z1=Math.max(z1,p.z);}const k=Math.min((w-pad*2)/(x1-x0),(h-pad*2)/(z1-z0));return{k,ox:w/2-(x0+x1)/2*k,oy:h/2-(z0+z1)/2*k};}
function mapSvg(map){const f=mapFit(getTrack(map.id),200,120,10),points=getTrack(map.id).points.filter((_,i)=>i%6===0);const coords=[...points,points[0]].map(p=>`${(f.ox+p.x*f.k).toFixed(1)},${(f.oy+p.z*f.k).toFixed(1)}`).join(' ');const sc=getTrack(map.id).shortcuts.map(c=>`<polyline class="map-cut" points="${c.pts.filter((_,i)=>i%4===0||i===c.pts.length-1).map(p=>`${(f.ox+p.x*f.k).toFixed(1)},${(f.oy+p.z*f.k).toFixed(1)}`).join(' ')}"/>`).join('');return `<svg class="map-preview" viewBox="0 0 200 135" aria-hidden="true"><polyline class="map-shadow" points="${coords}"/><polyline class="map-line" points="${coords}"/>${sc}<circle cx="${(f.ox+getTrack(map.id).points[0].x*f.k).toFixed(1)}" cy="${(f.oy+getTrack(map.id).points[0].z*f.k).toFixed(1)}" r="4"/></svg>`;}
