  $('mobileStartButton').disabled=locked;$('mobileStartButton').innerHTML=(locked?'NOCH '+Math.max(0,activeMap.unlockXP-profile.totalXP)+' XP':chosenMode==='online'?'ONLINE-LOBBY':'RENNEN STARTEN')+' <span>'+(locked?'⌑':'↗')+'</span>';$('mapHud').querySelector('div>span').textContent=activeMap.name.toUpperCase();document.querySelector('.location-tag p').textContent=activeMap.name+' · '+activeMap.subtitle.split(' · ')[0];
