let garage=null,garageOpen=false,garageIndex=0;
function garageModel(){garage.setCar(createCar(chosenColor,'07',KARTS[garageIndex].id));}
function openGarage(){garage??=createGarage();garageIndex=Math.max(0,KARTS.findIndex(k=>k.id===chosenKart));garageModel();garageOpen=true;$('menuLayer').hidden=true;document.querySelector('header').classList.add('in-garage');let ui=$('garageUi');if(!ui){ui=document.createElement('div');ui.id='garageUi';ui.className='garage-ui';document.body.appendChild(ui);ui.addEventListener('click',onGarageClick);}ui.hidden=false;renderGarageUi();audio.bleep('click');}
