function renderGarageUi(){const k=KARTS[garageIndex],sel=k.id===chosenKart;$('garageUi').innerHTML=`<div class="g-panel"><div class="menu-kicker"><i></i> APEX GARAGE · FAHRZEUG ${garageIndex+1} / ${KARTS.length}</div><h1>${k.name}</h1><div class="g-tag">${k.tag}${sel?' <b>✓ IM EINSATZ</b>':''}</div><p>${k.desc}</p><div class="g-stats">${kartPct(k).map(([n,v])=>`<div><small>${n}</small><span><i style="width:${v}%"></i></span><b>${Math.round(v/10)}</b></div>`).join('')}</div><div class="g-colors"><small>LACKIERUNG</small><div>${COLORS.map(([c,name])=>`<button class="g-swatch${c===chosenColor?' selected':''}" data-gcolor="${c}" style="--swatch:${c}" title="${name}" aria-label="${name}"></button>`).join('')}</div></div><div class="g-actions"><button class="primary" data-g="select">${sel?'WEITER MIT DIESEM KART':'DIESES KART NEHMEN'} <span>↗</span></button><button class="secondary" data-g="back">Zurück zum Menü</button></div></div><button class="g-arrow left" data-g="prev" aria-label="Vorheriges Kart">‹</button><button class="g-arrow right" data-g="next" aria-label="Nächstes Kart">›</button><div class="g-dots">${KARTS.map((x,i)=>`<i class="${i===garageIndex?'on':''}"></i>`).join('')}</div><div class="g-hint">Ziehen zum Drehen · ← → blättern · Enter wählen</div>`;}
