function garageSelect(){chosenKart=KARTS[garageIndex].id;try{localStorage.setItem('apex-rush-kart',chosenKart);}catch{}core.setKart(chosenKart);updatePlayerColor(chosenColor);audio.bleep('lap');closeGarage();}
function onGarageClick(e){const b=e.target.closest('button');if(!b)return;if(b.dataset.gcolor){chosenColor=b.dataset.gcolor;try{localStorage.setItem('apex-rush-color',chosenColor);}catch{}updatePlayerColor(chosenColor);garageModel();renderGarageUi();return;}const a=b.dataset.g;if(a==='prev')garageStep(-1);if(a==='next')garageStep(1);if(a==='select')garageSelect();if(a==='back'){audio.bleep('click');closeGarage();}}
function kartPicker(){const k=kartById(chosenKart);return `<div class="choose-kart"><label>DEIN FAHRZEUG <b>${k.name.toUpperCase()} · ${k.tag}</b></label><div class="kart-buttons">${KARTS.map(x=>`<button class="kart-btn${x.id===chosenKart?' selected':''}" data-kart="${x.id}" aria-pressed="${x.id===chosenKart}"><b>${x.name}</b><small>${x.tag}</small></button>`).join('')}</div><div class="kart-stats">${kartStats(k).map(([n,v])=>`<span><small>${n}</small><i>${'<em></em>'.repeat(v)}${'<u></u>'.repeat(5-v)}</i></span>`).join('')}</div><p class="kart-desc">${k.desc}</p></div>`;}
function stylePoints(){return collectedCoins*25+Math.floor(Math.min(8,core.stats?.driftSeconds||0)*25);}
function setupCoins(){coinGroup=new THREE.Group();coins=[];const ringGeo=new THREE.TorusGeometry(.23,.055,6,16),chipGeo=new THREE.CylinderGeometry(.16,.16,.055,6),glowGeo=new THREE.CircleGeometry(.29,18),gold=new THREE.MeshStandardMaterial({color:0xf4cb55,metalness:.65,roughness:.25,emissive:0x976322,emissiveIntensity:.2}),inner=new THREE.MeshStandardMaterial({color:0xfff1a8,metalness:.45,roughness:.3}),glowMat=new THREE.MeshBasicMaterial({color:0xf3cb64,transparent:true,opacity:.22,side:THREE.DoubleSide,depthWrite:false});for(let i=0;i<12;i++){const s=sampleTrack((.055+i/12)%1),lane=i%3===0?-1.5:i%3===1?1.5:0,x=s.x+s.nx*lane,z=s.z+s.nz*lane,g=new THREE.Group();g.position.set(x,s.y+.72,z);const ring=new THREE.Mesh(ringGeo,gold),disc=new THREE.Mesh(chipGeo,inner);disc.rotation.x=Math.PI/2;g.add(ring,disc);const glow=new THREE.Mesh(glowGeo,glowMat);glow.rotation.x=-Math.PI/2;glow.position.set(x,s.y+.023,z);coinGroup.add(g,glow);coins.push({x,z,y:s.y,mesh:g,glow,taken:false,index:i});}scene.add(coinGroup);}
function resetCoins(){for(const c of coins){c.taken=false;c.mesh.visible=true;c.glow.visible=true;}}
function updateCoins(dt){for(const c of coins){if(c.taken)continue;c.mesh.rotation.y+=dt*1.8;c.mesh.position.y=c.y+.72+Math.sin(core.elapsed*3+c.index)*.06;if(Math.hypot(core.player.x-c.x,core.player.z-c.z)<.92&&Math.abs(core.player.y-c.y)<2){c.taken=true;c.mesh.visible=false;c.glow.visible=false;collectedCoins++;audio.bleep('coin');$('pointsHud').classList.remove('collected');void $('pointsHud').offsetWidth;$('pointsHud').classList.add('collected');}}}

function escapeText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function getNickname(){const field=$('onlineName');nickname=(field?.value||nickname).trim().slice(0,20)||'Rookie Pilot';try{localStorage.setItem('apex-rush-name',nickname);}catch{}return nickname;}
function openOnlineLobby(){chosenMode='online';onlineLobbyOpen=true;onlineMenuPaused=false;clearInput();core.setTrack(chosenMap);setRaceHud(false);renderOnlineLobby(true);}
function renderOnlineLobby(force=false){
  if(!onlineLobbyOpen||helpState)return;const state=network.state,key=state.role+'-'+(state.roomId||lobbyTab);
  if(!force&&lobbyRoleKey===key&&$('onlineRoster')){updateOnlineLobby();return;}
  lobbyRoleKey=key;
  const connectionHelp=`<details class="online-help"${networkSettings.custom||networkSettings.forceRelay?' open':''}><summary>Wenn die Verbindung nicht klappt</summary><p>Uni- und Firmen-WLANs (z. B. eduroam) blockieren oft Direktverbindungen zwischen Geräten. Lösung: beim Erstellen den <b>Uni-WLAN-Modus</b> anhaken – Raumcodes mit <b>R</b> am Anfang laufen dann komplett über einen Server auf Port 443. Ohne diesen Modus versucht das Spiel einen Direktweg und einen kostenlosen Relay-Server (TURN). Klappt es trotzdem nicht: <b>alle Geräte in denselben Handy-Hotspot</b>, oder unten einen eigenen TURN-Zugang eintragen (z. B. kostenloses Metered-Konto, Link „…/api/v1/turn/credentials?apiKey=…“). Beide Seiten brauchen dieselbe Einstellung.</p><label class="net-label" for="netIce">EIGENER TURN-ZUGANG (LINK ODER JSON)</label><textarea id="netIce" rows="2" spellcheck="false" placeholder="https://deine-app.metered.live/api/v1/turn/credentials?apiKey=…">${escapeText(networkSettings.custom)}</textarea><label class="net-check"><input type="checkbox" id="netRelay" ${networkSettings.forceRelay?'checked':''}> Nur über Relay verbinden (für sehr strenge Netze)</label><button class="secondary" data-net="save">Netzwerk-Einstellung speichern</button></details>`;
  if(state.role==='idle'){
    menu(`<div class="online-kicker">ONLINE MULTIPLAYER · EIN RAUMCODE</div><h2 class="online-title">Ein Code. <em>Euer Rennen.</em></h2><p>Du erstellst den Raum. Deine Freunde geben nur den kurzen Raumcode ein – und sind dabei.</p><div class="online-lobby-grid"><div class="lobby-column"><div class="connection-tabs"><button class="${lobbyTab==='host'?'selected':''}" data-online="tab-host">RAUM ERSTELLEN</button><button class="${lobbyTab==='join'?'selected':''}" data-online="tab-join">BEITRETEN</button></div><div class="online-field"><label for="onlineName">DEIN FAHRERNAME</label><input id="onlineName" maxlength="20" autocomplete="off" value="${escapeText(nickname)}" placeholder="Rookie Pilot"></div>${lobbyTab==='host'?`<label class="net-check uni-mode"><input type="checkbox" id="uniMode" ${networkSettings.uniMode?'checked':''}> <span><b>Über Server spielen</b> (empfohlen, auch im eduroam): alle verbinden sich mit dem Apex-Rush-Server, von dem dieses Spiel geladen wurde. Aus = direkte Peer-to-Peer-Verbindung.</span></label><label class="net-check uni-mode"><input type="checkbox" id="onlineBots" ${wantsOnlineBots()?'checked':''}> <span><b>Mit KI-Fahrern auffüllen</b>: freie Startplätze bis 8 Autos bekommen KI-Gegner (laufen beim Gastgeber).</span></label><button class="primary" data-online="create-room">LOBBY ERSTELLEN <span>↗</span></button>`:'<div class="online-field"><label for="joinRoomCode">RAUMCODE VOM GASTGEBER</label><input id="joinRoomCode" class="room-code-entry" maxlength="16" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="ABCD-EFGH"></div><button class="primary" data-online="join-room">RAUM BEITRETEN <span>↗</span></button>'}<div id="onlineStatus" class="connection-status"></div><button class="secondary" data-online="leave">Zurück zur Garage</button></div><div class="lobby-column"><div class="lobby-meta"><span>SO KOMMT IHR AUF DIE STRECKE</span><b>2–8 FAHRER</b></div><ol class="online-steps"><li><b>Du erstellst eine Lobby.</b><span>Schicke den Raumcode an deine Freunde. Du selbst musst keinen Code eingeben.</span></li><li><b>Freunde geben den Code ein.</b><span>Unter „Beitreten“ verbinden sie sich automatisch mit deinem Raum.</span></li><li><b>Alle bereit? Los geht's!</b><span>Wählt eine Strecke, klickt „Bereit“ und startet gemeinsam.</span></li></ol><p class="online-help">Ein gemeinsamer Code für die ganze Lobby. Online könnt ihr euch gegenseitig rammen. Alle drei Strecken stehen euch online zur Verfügung. Jeder braucht die aktuelle Spieldatei und Internet.</p>${connectionHelp}</div></div>`);
  }else{
    const host=state.role==='host';
    menu(`<div class="online-kicker">ONLINE LOBBY · ${host?'DU BIST GASTGEBER':'MIT FREUNDEN SPIELEN'}</div><h2 class="online-title">Eure <em>Startaufstellung.</em></h2><div class="online-lobby-grid"><div class="lobby-column"><div class="lobby-meta"><span>DEINE LOBBY</span><b id="lobbyCount">${state.players.length} / 8 FAHRER${state.route==='server'?' · ÜBER SERVER':state.route==='relay'?' · ÜBER RELAY':state.route==='direct'?' · DIREKT':''}</b></div><div class="online-roster" id="onlineRoster"></div><div class="online-field"><span>${host?'STRECKE WÄHLEN':'STRECKE DES GASTGEBERS'}</span><div id="onlineMapPicker" class="online-map-picker"></div>${host?`<div class="mode-switch cc-switch lobby-cc" role="group" aria-label="Geschwindigkeitsklasse">${SPEED_CLASSES.map(cc=>`<button class="${cc===chosenClass?'selected':''}" data-cc="${cc}" aria-pressed="${cc===chosenClass}">${cc} KM/H</button>`).join('')}</div>`:'<p class="online-pause-note">Die Geschwindigkeit wählt der Gastgeber.</p>'}</div><div class="online-actions"><button class="small-button" id="onlineReady" data-online="ready">ICH BIN BEREIT</button>${host?'<button class="primary" id="onlineStart" data-online="start" disabled>AUF FAHRER WARTEN <span>↗</span></button>':'<p id="onlineGuestWait" class="online-pause-note">Verbindung wird hergestellt …</p>'}</div><div id="onlineStatus" class="connection-status"></div><button class="secondary" data-online="leave">Lobby verlassen · Zur Garage</button></div><div class="lobby-column"><div class="lobby-meta"><span>${host?'FREUNDE EINLADEN':'DEIN RAUM'}</span><b>EIN CODE FÜR ALLE</b></div><div class="online-field room-code-card"><label for="roomCode">RAUMCODE</label><input id="roomCode" class="room-code-display" readonly value="${formatRoomCode(state.roomCode)}" placeholder="Wird erstellt …"><button class="small-button" id="copyRoomCode" data-online="copy" data-target="roomCode">RAUMCODE KOPIEREN</button></div><p class="online-help">${host?'Schicke diesen Code an bis zu sieben Freunde. Sie wählen „Beitreten“ und geben ihn ein. Du musst nichts zurückkopieren oder bestätigen.':'Du bist im Raum. Weitere Freunde können mit demselben Code beitreten, solange Platz ist.'}</p><p class="online-help">Der Raum bleibt offen, solange der Gastgeber seine Lobby geöffnet lässt. Für eine Revanche braucht ihr keinen neuen Code.</p>${connectionHelp}</div></div>`);
  }
  $('menu').classList.add('multiplayer-menu');updateOnlineLobby();
}
function updateOnlineLobby(){{const st=network.state,el=$('lobbyCount');if(el)el.textContent=st.players.length+' / 8 FAHRER'+(st.route==='server'?' · ÜBER SERVER':st.route==='relay'?' · ÜBER RELAY':st.route==='direct'?' · DIREKT':'');}
  if(!onlineLobbyOpen)return;const state=network.state,self=state.players.find(p=>p.id===state.selfId);
  if($('onlineRoster')){$('onlineRoster').innerHTML=state.players.map(p=>`<div class="online-player"><i class="player-dot" style="background:${p.color}"></i><b>${escapeText(p.name)}${p.id===state.selfId?'<span class="you-tag">DU</span>':''}</b><span class="ready-badge ${!p.connected?'left':p.ready?'ready':'waiting'}">${!p.connected?'VERBINDET …':p.ready?'BEREIT':'WARTET'}</span></div>`).join('');}
  if($('onlineMapPicker'))$('onlineMapPicker').innerHTML=MAPS.map(m=>`<button class="${state.mapId===m.id?'selected':''}" data-online="map" data-map-id="${m.id}" ${state.role!=='host'||state.status!=='lobby'?'disabled':''}>${m.name}</button>`).join('');
  if($('onlineReady')){$('onlineReady').textContent=self?.ready?'✓ BEREIT · ZURÜCKNEHMEN':'ICH BIN BEREIT';$('onlineReady').disabled=state.status!=='lobby'||!self?.connected;$('onlineReady').classList.toggle('selected',!!self?.ready);}
  if($('onlineStart')){$('onlineStart').disabled=!network.canStart||lobbyBusy;$('onlineStart').innerHTML=(state.players.length<2?'MINDESTENS 2 FAHRER':network.canStart?'GEMEINSAM STARTEN':'ALLE MÜSSEN BEREIT SEIN')+' <span>↗</span>';}
  if($('onlineGuestWait'))$('onlineGuestWait').textContent=state.status==='connecting'?'Verbindung wird automatisch hergestellt …':state.status==='results'?'Der Gastgeber bereitet die nächste Runde vor.':self?.ready?'Du bist bereit. Der Gastgeber startet das Rennen.':'Verbindung steht. Klicke „Ich bin bereit“.';
  if($('onlineStatus')){$('onlineStatus').textContent=state.error||lobbyMessage;$('onlineStatus').classList.toggle('error',!!state.error);$('onlineStatus').classList.toggle('ok',!state.error&&state.status==='lobby'&&state.players.length>1);}
  if($('roomCode'))$('roomCode').value=formatRoomCode(state.roomCode);if($('copyRoomCode'))$('copyRoomCode').disabled=!state.roomCode;document.querySelectorAll('[data-online="create-room"],[data-online="join-room"]').forEach(b=>b.disabled=lobbyBusy);
}
function handleOnlineAction(button){runOnlineAction(button).catch(error=>{if(!onlineLobbyOpen)return;lobbyMessage=error.message||'Die Verbindung konnte nicht hergestellt werden.';updateOnlineLobby();toast(lobbyMessage,4500);});}
async function runOnlineAction(button){
  const action=button.dataset.online;
  if(action==='tab-host'||action==='tab-join'){getNickname();lobbyTab=action==='tab-host'?'host':'join';lobbyRoleKey='';renderOnlineLobby(true);return;}
  if(action==='copy'){const field=$(button.dataset.target);if(!field?.value){toast('Der Verbindungscode ist noch nicht bereit.');return;}try{await navigator.clipboard.writeText(field.value);toast('Code kopiert. Jetzt an deinen Freund schicken.',1800);}catch{field.focus();field.select();toast('Code markiert – mit Strg+C kopieren.',2400);}return;}
  if(action==='leave'){leaveOnline();return;}
  if(action==='ready'){const state=network.state,self=state.players.find(p=>p.id===state.selfId);network.setReady(!self?.ready);return;}
  if(action==='map'){network.setMap(button.dataset.mapId);return;}
  if(action==='start'){network.startRace({cc:chosenClass});return;}
  if(action==='lobby'){onlineMenuPaused=false;onlineFinishData=null;onlineAward=null;if(network.isHost)network.restartLobby();if(network.state.status==='lobby'){onlineRace=null;core.setTrack(chosenMap);clearRemoteCars();setRaceHud(false);}onlineLobbyOpen=true;lobbyRoleKey='';renderOnlineLobby(true);return;}
  if(lobbyBusy)return;lobbyBusy=true;updateOnlineLobby();
  try{
    if(action==='create-room'){getNickname();lobbyMessage='Raum wird erstellt …';updateOnlineLobby();networkSettings.uniMode=!!$('uniMode')?.checked;setOnlineBots(!!$('onlineBots')?.checked);await network.hostRoom({name:nickname,color:chosenColor,mapId:chosenMap,relay:networkSettings.uniMode});lobbyMessage='Raumcode teilen. Deine Freunde verbinden sich automatisch.';}
    if(action==='join-room'){const code=$('joinRoomCode')?.value||'';getNickname();lobbyMessage='Raum wird verbunden …';updateOnlineLobby();await network.joinRoom({code,name:nickname,color:chosenColor});lobbyMessage='Verbindung steht. Bereit für das Rennen?';}
  }finally{lobbyBusy=false;updateOnlineLobby();}
}
function onOnlineChange(state){
  if(intentionalLeave)return;
  if(state.role!=='idle'&&state.mapId!==chosenMap&&!onlineRace){onlineLobbyOpen=true;selectMap(state.mapId);}
  if(onlineRace&&state.status==='lobby'&&onlineLastStatus!=='lobby'){helpState=null;onlineRace=null;onlineMenuPaused=false;onlineFinishData=null;onlineAward=null;core.setTrack(chosenMap);clearRemoteCars();setRaceHud(false);onlineLobbyOpen=true;lobbyRoleKey='';renderOnlineLobby(true);}
  onlineLastStatus=state.status;
  if(onlineLobbyOpen){if(lobbyRoleKey!==state.role+'-'+(state.roomId||lobbyTab))renderOnlineLobby(true);else updateOnlineLobby();}
  if(onlineFinishData&&state.status==='racing'&&$('onlineWaitingRows'))$('onlineWaitingRows').innerHTML=onlineStandingsRows();
  for(const p of state.players){const entry=remoteCars.get(p.id);if(entry)entry.car.visible=p.connected&&!p.dnf;}
}
function onOnlineEvent(event){
  if(intentionalLeave)return;
  if(event.type==='start')beginOnlineRace(event.race);
  if(event.type==='results')showOnlineResults(event.results);
  if(event.type==='closed'){
    helpState=null;clearInput();onlineMenuPaused=false;onlineRace=null;onlineLobbyOpen=false;onlineFinishData=null;clearRemoteCars();core.setTrack(chosenMap);setRaceHud(false);
    menu(`<div class="online-kicker">VERBINDUNG GETRENNT</div><h2 class="online-title">Zurück in die Box.</h2><p>${escapeText(event.reason)}</p><p>Dein bereits gespeicherter Karrierefortschritt bleibt erhalten.</p><button class="primary" data-online="leave">ZUR GARAGE <span>↗</span></button>`);$('menu').classList.add('multiplayer-menu');
  }
}
function beginOnlineRace(race){
  if(onlineRace?.id===race.id)return;const state=network.state;onlineLobbyOpen=false;onlineRace={...race};onlineMenuPaused=false;onlineFinishData=null;onlineAward=null;helpState=null;clearRemoteCars();chosenMode='online';
  if(chosenMap!==state.mapId)selectMap(state.mapId);
  const own=state.players.find(p=>p.id===state.selfId);if(own)updatePlayerColor(own.color);
  launchingOnline=true;startRace();launchingOnline=false;raceId=race.id+'-'+state.selfId;core.countdown=Math.max(.001,(race.startAt-network.now())/1000);
  const slot=state.players.findIndex(p=>p.id===state.selfId);const g=placeOnlineCar({},slot);Object.assign(core.player,{x:g.x,z:g.z,angle:g.angle});core._playerTrackProgress=g.progress;core._lastTrackT=g.t;
  onlineBots.clear();botHitQueue.length=0;seenBotHits.clear();rivalCars.forEach(c=>c.visible=false);
  if(state.role==='host'&&wantsOnlineBots()&&state.players.length<GRID_SIZE){const slots=[];for(let k=state.players.length;k<GRID_SIZE;k++)slots.push(gridPlacement(track,k));core.addBots(slots);}
  state.players.forEach((p,i)=>{if(p.id===state.selfId)return;const car=createCar(p.color,String(i+1).padStart(2,'0'));const start={};placeOnlineCar(start,i);car.position.set(start.x,start.y||0,start.z);car.rotation.y=start.angle;car.add(onlineNameTag(p.name));scene.add(car);remoteCars.set(p.id,{car,color:p.color,name:p.name,target:{...start,speed:0,steer:0,boosting:false,drifting:false},received:performance.now()});});
  onlineLastSend=0;clearInput();$('menuLayer').hidden=true;toast(state.players.length+' FAHRER'+(core.rivals.length?' + '+core.rivals.length+' KI':'')+' · '+(race.cc||80)+' KM/H',2200);
}
function placeOnlineCar(car,slot){const g=gridPlacement(track,slot);car.x=g.x;car.z=g.z;car.y=g.y;car.angle=g.angle;car.progress=g.progress;car.t=g.t;return g;}
function onlineNameTag(name){const c=document.createElement('canvas');c.width=512;c.height=88;const x=c.getContext('2d');x.fillStyle='#112d36dd';x.beginPath();x.roundRect(4,4,504,80,15);x.fill();x.font='700 37px Arial';x.fillStyle='#eef3e3';x.textAlign='center';x.textBaseline='middle';x.fillText(name,256,46,470);const map=new THREE.CanvasTexture(c);map.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map,transparent:true,depthTest:false}));sprite.scale.set(2.3,.4,1);sprite.position.y=1.1;sprite.renderOrder=5;return sprite;}
function clearRemoteCars(){for(const entry of remoteCars.values())if(scene)destroyCar(entry.car);remoteCars.clear();onlineBots.clear();core.keepBotsRacing=false;}
function onRemoteState(event){const entry=remoteCars.get(event.id);if(!entry||!onlineRace)return;entry.target=event.state;entry.received=performance.now();if(event.state.bots?.length&&!core.keepBotsRacing&&event.id===network.state.hostId)onBotsFromHost(event.state.bots);if(core.keepBotsRacing)for(const h of event.state.hits||[]){if(seenBotHits.has(h.id))continue;seenBotHits.add(h.id);core.remoteBotHit(h.bot,h.k);}}
function tickOnline(dt,ms){
  // Remote cars become solid obstacles for the local car (used by core on the next step).
  const ext=[];
  for(const [rid,entry] of remoteCars){const t=entry.target,v=smoothEntry(entry,dt);if(t.kart&&entry.car.userData.kart!==t.kart){const old=entry.car,tag=old.children.find(o=>o.isSprite);entry.car=createCar(entry.color,old.name.slice(-2),t.kart);if(tag){old.remove(tag);entry.car.add(tag);}scene.add(entry.car);destroyCar(old);}entry.car.position.set(entry.rx,entry.ry,entry.rz);entry.car.rotation.y=entry.yaw+(t.spinA||0);entry.car.rotation.x=-(entry.pitch||0);ext.push({key:'p:'+rid,x:entry.rx,z:entry.rz,y:entry.ry,mass:t.mass||1,trail:t.trail||null,progress:t.progress,speed:t.speed,angle:entry.yaw,vx:v.vx,vz:v.vz,name:entry.name,star:!!t.star,ghost:performance.now()-entry.received>1500});entry.car.visible=true;rocketVisual('o'+entry.name,entry.car,t.rocket?{x:entry.car.position.x,z:entry.car.position.z,y:entry.ry,angle:entry.yaw,rocketT:1}:null,performance.now());starPaint(entry.car,!!t.star,performance.now());animateCar(entry.car,t,dt);}
  core.externals=[...ext,...tickOnlineBots(dt,ms)];const fr=onlineFieldList();core.onlineCount=fr.length;core.rankFrac=()=>{const r=onlineFieldRank();return r.n>1?(r.rank-1)/(r.n-1):.5;};
  while(botHitQueue.length&&performance.now()-botHitQueue[0].t>1200)botHitQueue.shift();
  if(ms-onlineLastSend>(network.state.signaling==='relay'?66:50)&&['countdown','racing'].includes(core.status)){onlineLastSend=ms;network.publishState({...core.player,progress:core.playerProgress,lap:core.lap,elapsed:core.elapsed,items:core.ownItemsForNet(),star:core.player.starT>0||core.player.rocketT>0,rocket:core.player.rocketT>0,spinA:core.player.spinAngle||0,bots:core.keepBotsRacing?core.botsForNet():undefined,hits:botHitQueue.map(h=>({id:h.id,bot:h.bot,k:h.k}))});}
}
function sortedOnlinePlayers(){const state=network.state;return state.players.map(p=>p.id===state.selfId?{...p,progress:core.playerProgress,finishedTime:onlineFinishData?.time??p.finishedTime}:p).sort((a,b)=>{if(a.finishedTime!==null&&b.finishedTime!==null)return a.finishedTime-b.finishedTime;if(a.finishedTime!==null)return -1;if(b.finishedTime!==null)return 1;if(a.dnf!==b.dnf)return a.dnf?1:-1;return b.progress-a.progress;});}
function onlineRank(){const state=network.state;return Math.max(1,sortedOnlinePlayers().findIndex(p=>p.id===state.selfId)+1);}
function renderOnlineLeaderboard(){$('driverRows').innerHTML=onlineFieldList().map((p,i)=>`<div class="driver${p.self?' self':''}" style="--driver-color:${p.color}"><span class="rank">${i+1}</span><span class="driver-color"></span><b>${escapeText(p.name)}</b><small>${p.bot?'KI':p.dnf?'DNF':p.finished?'ZIEL':p.self?'DU':'LIVE'}</small></div>`).join('');}
function pauseOnlineRace(){if(!['racing','countdown'].includes(core.status))return;onlineMenuPaused=true;clearInput();$('pause').textContent='▶';menu('<div class="online-kicker">ONLINE-RENNEN LÄUFT WEITER</div><h2>Kurz in die Box?</h2><p class="online-pause-note">Dein Auto bremst ab. Die anderen Fahrer und die Rennzeit fahren weiter.</p><button class="primary" data-action="resume">WEITERFAHREN <span>↗</span></button><button class="secondary" data-online="leave">Rennen verlassen</button>');}
function onlineStandingsRows(results=null){const state=network.state,rows=results||sortedOnlinePlayers();return rows.map((p,i)=>`<div class="online-result ${i===0?'winner':''} ${p.id===state.selfId?'self':''} ${p.dnf?'dnf':''}"><span>${p.place||i+1}</span><i class="player-dot" style="background:${p.color}"></i><b>${escapeText(p.name)}${p.id===state.selfId?' <small>DU</small>':''}</b><strong>${p.dnf?'DNF':p.time!==undefined&&p.time!==null?formatTime(p.time):p.finishedTime!==null?formatTime(p.finishedTime):'FÄHRT …'}</strong></div>`).join('');}
function finishOnline(event){
  if(onlineFinishData)return;helpState=null;clearInput();onlineMenuPaused=false;onlineFinishData={time:event.time,bestLap:event.bestLap,stats:{...core.stats},coins:collectedCoins};
  menu(`<div class="online-kicker">DU BIST IM ZIEL</div><h2 class="online-title">${formatTime(event.time)}</h2><p>Die anderen Fahrer sind noch unterwegs. Maximal 30 Sekunden bis zur gemeinsamen Ergebnisliste.</p><div class="online-results" id="onlineWaitingRows">${onlineStandingsRows()}</div><p class="online-help">Lass das Spiel geöffnet. Punkte und XP gibt es mit dem offiziellen Rennergebnis.</p>`);$('menu').classList.add('multiplayer-menu');audio.bleep('finish');network.finishRace(onlineFinishData);
}
function showOnlineResults(results){
  if(!onlineRace)return;helpState=null;clearInput();onlineMenuPaused=false;core.status='finished';core.player.boosting=false;const state=network.state,own=results.find(p=>p.id===state.selfId);let award=null;
  if(own&&!own.dnf&&onlineFinishData&&!onlineAward){const result=calculateResult({raceId:onlineRace.id+'-'+state.selfId,map:{...activeMap,parTimes:parFor(activeMap,core.cc||80)},mode:recordMode('online',core.cc||80),time:own.time,bestLap:onlineFinishData.bestLap,position:own.place,stats:onlineFinishData.stats,coins:onlineFinishData.coins,completed:true});award=applyResult(profile,result);profile=award.profile;onlineAward=award;if(!saveProfile(profile)&&!saveWarning){saveWarning=true;toast('Speichern ist hier blockiert. Der Fortschritt bleibt für diese Sitzung.',4000);}}
  award=award||onlineAward;const level=getLevel(profile.totalXP);
  menu(`<div class="online-kicker">ONLINE GRAND PRIX · GEMEINSAMES ERGEBNIS</div><h2 class="online-title">${own?.dnf?'Nächste Runde zählt.':own?.place===1?'Online-Champion!':'Starkes Rennen.'}</h2><div class="online-results">${onlineStandingsRows(results)}</div>${award?`<div class="reward-summary"><div><strong>+${award.pointsEarned.toLocaleString('de-DE')}</strong><span>PUNKTE <b>+${award.xpEarned} XP</b></span></div></div><div class="finish-career"><span>LVL ${level.level} · ${level.title}</span><b>${profile.totalXP} XP</b><div><i style="width:${level.progress*100}%"></i></div></div>${award.newMaps.length?'<div class="unlock-notice">NEUE KARRIERE-STRECKE FREIGESCHALTET!</div>':''}`:'<p class="online-help">Ohne Zieleinlauf gibt es keine Rennpunkte. Versuche es in der nächsten Runde!</p>'}<div class="online-buttons"><button class="primary" data-online="lobby">${network.isHost?'NÄCHSTE RUNDE VORBEREITEN':'ZUR LOBBY'} <span>↗</span></button><button class="small-button" data-online="leave">LOBBY VERLASSEN</button></div>`);$('menu').classList.add('multiplayer-menu');$('countdown').hidden=true;audio.bleep('finish');
}
function leaveOnline(){intentionalLeave=true;network.leave();onlineRace=null;onlineLobbyOpen=false;onlineMenuPaused=false;onlineFinishData=null;onlineAward=null;lobbyRoleKey='';lobbyMessage='';clearRemoteCars();toGarage();intentionalLeave=false;}

window.addEventListener('pointerdown',e=>{if(garageOpen&&e.target===renderer?.domElement)garage.dragStart(e.clientX);});window.addEventListener('pointermove',e=>{if(garageOpen)garage.dragMove(e.clientX);});window.addEventListener('pointerup',()=>garage?.dragEnd());
window.addEventListener('beforeunload',()=>network.leave(true));
